
#' Plot One-Way Sensitivity Analysis Tornado Diagrams
#'
#' Produces tornado diagrams based on deterministic one-way sensitivity
#' analysis results generated by \code{\link{compute_owsa}}.
#'
#' Tornado diagrams illustrate the impact of varying individual model
#' parameters between predefined lower and upper values on incremental
#' cost-effectiveness outcomes.
#'
#' The function supports multiple intervention strategies compared against
#' a common reference strategy, alternative economic outcomes, flexible
#' colour mappings, filtering and comparison-specific faceting.
#'
#' Horizontal segments represent deviations from the baseline outcome
#' under lower and upper parameter scenarios. Dashed vertical lines
#' identify the corresponding baseline estimates.
#'
#' @param data An object of class \code{owsa_result}, typically generated
#'   by \code{\link{compute_owsa}}.
#'
#' @param group Optional character vector identifying the alternative
#'   strategies to display. If \code{NULL}, all available comparisons
#'   are included.
#'
#' @param metric Character string specifying the economic outcome to
#'   visualize. Available options are \code{"icer"}, \code{"nmb"},
#'   \code{"delta_cost"} and \code{"delta_effect"}.
#'   Defaults to \code{"nmb"}.
#'
#' @param color_by Character string specifying the variable used for
#'   colour mapping. Defaults to \code{"scenario"}, distinguishing
#'   lower and upper parameter scenarios. Use \code{"none"} to
#'   disable colour mapping.
#'
#' @param facet_by Character string controlling faceting. Available
#'   options are \code{"comparison"} and \code{"none"}.
#'   When \code{"none"} is selected, a single comparison must
#'   be specified or available.
#'
#' @param filter_expr Optional character string containing a filtering
#'   expression evaluated against the sensitivity results.
#'
#' @param facet_scales Character string controlling axis scales across
#'   comparison panels. Defaults to \code{"free_x"}, allowing each
#'   comparison to use an independent horizontal scale.
#'
#' @param palette Colour palette passed to the internal plotting engine
#'   \code{\link{ce_plot_base}}. Defaults to a named vector assigning
#'   blue to lower scenarios and red to upper scenarios.
#'
#' @param return_data Logical; if \code{TRUE}, returns the underlying
#'   tidy sensitivity data instead of a \code{ggplot} object.
#'
#' @details
#' For each parameter and comparison, the function extracts baseline,
#' lower and upper scenario outcomes.
#'
#' Parameter impact is calculated as the absolute difference between
#' upper and lower scenario outcomes:
#'
#' \deqn{Impact = |Outcome_{upper} - Outcome_{lower}|}
#'
#' Parameters are ordered according to their maximum impact across
#' the available comparisons, ensuring a consistent ordering between
#' facets.
#'
#' Each scenario is represented by a horizontal segment connecting
#' its outcome to the baseline estimate. Consequently, the displayed
#' segments represent deviations from baseline rather than confidence
#' intervals.
#'
#' The function uses the internal plotting engine
#' \code{\link{ce_plot_base}} to maintain consistent aesthetics
#' across CEAgroupR visualizations.
#'
#' The analysis is deterministic and does not incorporate bootstrap
#' sampling uncertainty.
#'
#' @return
#' A \code{ggplot} object representing the tornado diagram, or a
#' tidy data frame containing scenario-specific outcomes, baseline
#' estimates, impact measures and plotting coordinates when
#' \code{return_data = TRUE}.
#'
#' @examples
#' ## Example 1: Compute one-way sensitivity analysis
#' owsa_parameters <- data.frame(
#'   parameter = c("gp_visit", "specialist_visit", "hospital_day"),
#'   resource  = c("gp_visits", "specialist_visits", "hospital_days"),
#'   base      = c(65, 120, 650),
#'   lower     = c(50, 90, 500),
#'   upper     = c(80, 150, 800)
#' )
#'
#' res_owsa <- compute_owsa(
#'   data       = cua_example,
#'   group      = "group",
#'   cost       = "cost_total",
#'   effect     = "effect",
#'   ref        = "usual_care",
#'   parameters = owsa_parameters
#' )
#'
#' ## Example 2: Tornado diagram of incremental NMB
#' plot.tornado(res_owsa, metric = "nmb")
#'
#' ## Example 3: ICER sensitivity for a selected strategy
#' plot.tornado(
#'   res_owsa,
#'   group    = "exercise_A",
#'   metric   = "icer",
#'   facet_by = "none"
#' )
#'
#' ## Example 4: Extract sensitivity data
#' tornado_data <- plot.tornado(
#'   res_owsa,
#'   metric      = "delta_cost",
#'   return_data = TRUE
#' )
#'
#' @export plot.tornado
#' @export


plot.tornado <- function(
    data,
    group = NULL,
    metric = "nmb",
    color_by = "scenario",
    facet_by = "comparison",
    filter_expr = NULL,
    facet_scales = "free_x",
    palette = c(lower = "#4472C4", upper = "#C0504D"),
    return_data = FALSE
) {

  # ---------------------------------------------------------------------------
  # 1. Input validation
  # ---------------------------------------------------------------------------
  if (!inherits(data, "owsa_result")) {
    stop("'data' must be an owsa_result object.")
  }

  metric <- match.arg(
    metric,
    c("icer", "nmb", "delta_cost", "delta_effect")
  )

  facet_by <- match.arg(
    facet_by,
    c("comparison", "none")
  )

  df <- data$sensitivity_results
  df$comparison <- df$group

  if (!is.null(group)) {
    df <- df[df$group %in% group, , drop = FALSE]
  }

  if (!is.null(filter_expr)) {
    df <- dplyr::filter(
      df,
      !!rlang::parse_expr(filter_expr)
    )
  }

  if (nrow(df) == 0L) {
    stop("No observations available after filtering.")
  }

  # ---------------------------------------------------------------------------
  # 2. Prepare sensitivity results
  # ---------------------------------------------------------------------------
  keys <- c("comparison", "parameter")

  extract_scenario <- function(scenario, value_name) {
    out <- df[
      df$scenario == scenario,
      c(keys, metric),
      drop = FALSE
    ]

    names(out)[3] <- value_name
    out
  }

  baseline <- extract_scenario("baseline", "baseline")
  lower    <- extract_scenario("lower", "lower_value")
  upper    <- extract_scenario("upper", "upper_value")

  tornado <- merge(
    merge(baseline, lower, by = keys),
    upper,
    by = keys
  )

  if (nrow(tornado) == 0L) {
    stop("Complete sensitivity scenarios are required.")
  }

  tornado$impact <- abs(
    tornado$upper_value - tornado$lower_value
  )

  # ---------------------------------------------------------------------------
  # 3. Prepare plotting data
  # ---------------------------------------------------------------------------
  tornado_long <- rbind(
    transform(
      tornado,
      scenario = "lower",
      value = lower_value
    ),
    transform(
      tornado,
      scenario = "upper",
      value = upper_value
    )
  )

  tornado_long$scenario <- factor(
    tornado_long$scenario,
    levels = c("lower", "upper")
  )

  tornado_long$segment_start <- tornado_long$baseline
  tornado_long$segment_end   <- tornado_long$value

  # Order parameters by maximum impact across comparisons
  ranking <- stats::aggregate(
    impact ~ parameter,
    data = tornado,
    FUN = max
  )

  ranking <- ranking[
    order(ranking$impact, ranking$parameter),
  ]

  tornado_long$parameter <- factor(
    tornado_long$parameter,
    levels = ranking$parameter
  )

  if (return_data) {
    return(tornado_long)
  }

  # ---------------------------------------------------------------------------
  # 4. Resolve aesthetics through ce_plot_base()
  # ---------------------------------------------------------------------------
  base <- ce_plot_base(
    data = tornado_long,
    color_by = color_by,
    facet_by = "none",
    facet_scales = facet_scales,
    palette = palette
  )

  # ---------------------------------------------------------------------------
  # 5. Build tornado plot
  # ---------------------------------------------------------------------------
  p <- ggplot2::ggplot(
    base$data,
    ggplot2::aes(
      x = segment_start,
      xend = segment_end,
      y = parameter,
      yend = parameter
    )
  ) +
    base$plot$theme

  if (!is.null(base$color_var)) {

    p <- p +
      ggplot2::geom_segment(
        ggplot2::aes(
          colour = .data[[base$color_var]]
        ),
        linewidth = 8,
        lineend = "butt"
      ) +
      ggplot2::scale_colour_manual(
        values = base$palette_values
      )

  } else {

    p <- p +
      ggplot2::geom_segment(
        colour = "#4472C4",
        linewidth = 8,
        lineend = "butt"
      )
  }

  # ---------------------------------------------------------------------------
  # 6. Baseline reference lines
  # ---------------------------------------------------------------------------
  baseline_lines <- unique(
    tornado[, c("comparison", "baseline")]
  )

  p <- p +
    ggplot2::geom_vline(
      data = baseline_lines,
      ggplot2::aes(xintercept = baseline),
      inherit.aes = FALSE,
      linetype = "dashed",
      linewidth = 0.6
    )

  # ---------------------------------------------------------------------------
  # 7. Faceting
  # ---------------------------------------------------------------------------
  if (facet_by == "comparison") {

    p <- p +
      ggplot2::facet_wrap(
        ggplot2::vars(comparison),
        scales = facet_scales
      )

  } else if (length(unique(tornado$comparison)) > 1L) {

    stop(
      "Select one group when facet_by = 'none'."
    )
  }

  # ---------------------------------------------------------------------------
  # 8. Labels
  # ---------------------------------------------------------------------------
  p <- p +
    ggplot2::labs(
      title = "One-way Sensitivity Analysis",
      subtitle = paste("Outcome:", metric),
      x = metric,
      y = NULL,
      colour = "Scenario"
    )

  return(p)
}
